import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"51、【震】 震下震上","description":"周易口訣義 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"周易口訣義 - 51、【震】 震下震上"},"headers":[],"relativePath":"classics/koujueyi/053.md","filePath":"classics/koujueyi/053.md"}'),r={name:"classics/koujueyi/053.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><p>彖曰：震，亨。「震來虩虩」，恐致福也；「笑言啞啞」，後有則也。「震驚百里」，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。</p><p>象曰：瀳雷，震；君子以恐懼修省。</p><p>初九，震來虩虩，後笑言啞啞，吉。</p><p>象曰：「震來虩虩」，恐致福也；「笑言啞啞」，後有則也。</p><p>六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。</p><p>象曰：「震來厲」，乘剛也。</p><p>六三，震蘇蘇，震行無眚。</p><p>象曰：「震蘇蘇」，位不當也。</p><p>九四，震遂泥。</p><p>象曰：「震遂泥」，未光也。</p><p>六五，震往來厲，億無喪，有事。</p><p>象曰：「震往來厲」，危行也；其事在中，大無喪也。</p><p>上六，震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。</p><p>象曰：「震索索」，中未得也；雖兇無咎，畏鄰戒也。</p><p>解讀</p><p>「震亨」者，震動也，此象雷之卦，雷是天之威動也。雷之威震，人皆驚懼，因此恐懼而乃修德，恭儉整肅，所以獲通，故曰</p><p>「震亨」也。「震來虩虩，笑言啞啞」者，虩虩恐懼之貌；啞啞語笑之聲，故迅雷風烈，君子為之變容。天既威震，人皆恐懼，不敢怠慢，遂乃修德，道成德立，福慶亦至，福至之後，方敢喜樂，故曰「笑言啞啞」也。震驚百里，不喪匕鬯者，匕者，其形如箄，可以舉鼎中之物也；鬯是香草，取之釀酒，祭廟之用也。震卦體屬長子，若君出於外，或為巡狩等事，即長子監臨於國，威震肅齊，廣及百里。百里者，取雷震百里之義，承主祭祀粢盛之器，守而不失，故曰「不喪匕鬯」也。象曰：「瀳雷震」者，瀳者，因仍之義；雷聲連續，威震相仍，雷電赫赫，故曰「瀳雷震」也。「君子以恐懼修省」者，恐，怖也；懼，驚駭也。君子立身，恆懷驚肅，若臨泉谷，如履薄冰，況遇天之威怒，彌益修身，省察己過也。</p><p>「初六，震來虩虩，後笑言啞啞，吉」者，以剛處卦之先，剛則不暗於幾先則能有前識，當威振之時，天威大行，而能懼以修德，遂至笑語之盛，吉福臻焉。</p><p>「六二，震來厲，億喪貝，躋於九陵，勿逐，七日得」者，初九以剛居下，因懼修德，即是有德之人。今六二不能敬剛陽，尊有德，而反乘之，即為天之所誅罰。故威震若來，即致危厲，哀嗟傷嗟，亡其資貨糧用之屬也，故曰「震來厲，億喪貝」也。億，傷嘆之辭也；貝者，資貨糧用之屬也。違天不敬，遂被天誅，懼天之威，而乃逃竄，威嚴大行，人不容舍，無糧而走，必將困危。雖超九陵，不過七日，為有司所獲，故曰「躋於九陵，勿逐，七日得」也。</p><p>六三「震蘇蘇，震行無眚」者，蘇蘇，是心懷憂慮不安之貌。六三履位不正，心恆憂慮，不獲安寧，故曰「震蘇蘇」也。雖心不安，而不乘剛，不為乖逆，故可以懼行而無災眚，故曰「震行無眚」也。</p><p>九四「震遂泥」者，泥，沉溺也。九四以剛陽之質，在四陰之中，為四陰之主，固宜挺身獨立，以安於眾。若以自懷恐懼，不能挺拔，即致泥溺，沉困於難。故鄭眾雲「身既不安，豈能安眾」是也。</p><p>六五：震往來，厲。億無喪，有事者，往即無應，來又乘剛，往之與來，不免危厲也。夫處威厲之時而居尊位，即是天助君命，威令大行，斯乃有事之機矣。故戒之曰：但保其位，守中自安，能高大其行，無所喪失，即懷大事，故曰「億無喪，有事」也。</p><p>上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。「婚媾有言」者，索索，不安不專之貌；矍矍，視不正、不審諦之容也。上六處震之極，是懼之極矣。既居極懼之地，而欲求安，亦不能得，故心懷不安，乃索索然，而所瞻視又不專審，乃矍矍矣。憂懼若此，更有徵，即將有兇危至，故曰「徵兇」也。若所懼之事，非是己作，若因鄰家有事，懼相連及，預先防戒，即得免咎，故曰「震不於其躬，於其鄰，無咎」。處極懼之時，雖復姻親，亦不無相疑之言，故曰「婚媾有言」也。</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
